{"op": "write", "path": "query.sql", "content": "WITH eligible AS (
 SELECT * FROM maintenance_windows WHERE status='active' AND start_tick<end_tick
), prior AS (
 SELECT *, MAX(end_tick) OVER (PARTITION BY tenant,asset ORDER BY start_tick,end_tick,interval_id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) AS previous_end FROM eligible
), marked AS (
 SELECT *,CASE WHEN previous_end IS NULL OR start_tick>previous_end THEN 1 ELSE 0 END AS new_segment FROM prior
), grouped AS (
 SELECT *,SUM(new_segment) OVER (PARTITION BY tenant,asset ORDER BY start_tick,end_tick,interval_id ROWS UNBOUNDED PRECEDING) AS segment FROM marked
), spans AS (
 SELECT tenant,asset,segment,MIN(start_tick) AS lo,MAX(end_tick) AS hi FROM grouped GROUP BY tenant,asset,segment
)
SELECT tenant,asset,SUM(hi-lo) AS covered_ticks,COUNT(*) AS segments FROM spans GROUP BY tenant,asset ORDER BY tenant,asset"}
